WITH flattened AS (SELECT id, plan, effective_from, currency, EXPLODE_OUTER(tier_prices) AS val FROM price_tiers), scored AS (SELECT *, DENSE_RANK() OVER w_recent AS val_dense_rank, SUM(val) OVER (PARTITION BY plan) AS plan_sum_val FROM flattened WINDOW w_recent AS (PARTITION BY currency ORDER BY val DESC)), base AS (SELECT id, effective_from, currency, val, val_dense_rank, INITCAP(TRIM(plan)) AS plan_title, CONCAT(plan, ', ', currency) AS plan_currency FROM scored WHERE plan_sum_val = 346), filtered AS (SELECT *, UPPER(currency) AS currency_upper FROM base WHERE effective_from >= DATE '2024-02-23') SELECT currency, CASE WHEN val_dense_rank >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_dense_rank_tier, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows_2, COUNT(*) AS event_count, APPROX_PERCENTILE(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles, COUNT(DISTINCT currency) AS distinct_currencies FROM filtered GROUP BY currency, CASE WHEN val_dense_rank >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING event_count >= 1 ORDER BY event_count NULLS FIRST
